from pathlib import Path
import base64, hashlib, io, json, sys, zipfile
root=Path(__file__).resolve().parents[1]
if len(sys.argv) != 2:
    raise SystemExit('Usage: python3 scripts/v4_prepare_corrected_gpu_smoke.py OUTPUT_DIR')
buf=io.BytesIO()
with zipfile.ZipFile(buf,'w',zipfile.ZIP_DEFLATED) as z:
    for p in (root/'src/rescuevision').rglob('*.py'): z.write(p,p.relative_to(root))
payload=base64.b64encode(buf.getvalue()).decode(); digest=hashlib.sha256(buf.getvalue()).hexdigest()
code=f'''import base64, hashlib, io, json, random, sys, time, zipfile\nfrom pathlib import Path\narchive=base64.b64decode({payload!r})\nif hashlib.sha256(archive).hexdigest() != {digest!r}: raise RuntimeError("Source hash mismatch")\nroot=Path("/kaggle/working/rv4_corrected_source"); root.mkdir(exist_ok=True)\nwith zipfile.ZipFile(io.BytesIO(archive)) as z: z.extractall(root)\nsys.path.insert(0,str(root/"src"))\nimport numpy as np\nimport torch\nfrom PIL import Image\nfrom torch import nn\nfrom torch.nn import functional as F\nfrom rescuevision.v4.datasets import _rasterize_xbd_label\nfrom rescuevision.v4.evaluation import OfficialAccumulator\nif not torch.cuda.is_available(): raise RuntimeError("CUDA required; no CPU fallback")\ntorch.manual_seed(42); random.seed(42); np.random.seed(42)\ninputs=Path("/kaggle/input")\nrepo=list(inputs.rglob("hubconf.py")); weights=list(inputs.rglob("*.pth"))\nif len(repo)!=1 or len(weights)!=1: raise RuntimeError(f"Expected one model repo and checkpoint: {{len(repo)}}, {{len(weights)}}")\npre_paths=sorted(inputs.rglob("*_pre_disaster.png")); records=[]\nfor pre in pre_paths:\n    split=pre.parent.parent\n    if split.name != "train": continue\n    sid=pre.name[:-len("_pre_disaster.png")]\n    post=pre.with_name(sid+"_post_disaster.png"); label=split/"labels"/(sid+"_post_disaster.json")\n    if not post.is_file() or not label.is_file(): raise RuntimeError(f"Missing input for {{sid}}")\n    event, _, suffix=sid.rpartition("_")\n    if not suffix.isdigit(): raise RuntimeError(f"Unexpected sample id {{sid}}")\n    records.append((sid,event,pre,post,label))\nif len(records)!=2799: raise RuntimeError(f"Expected 2799 labeled pairs, found {{len(records)}}")\nevents=sorted({{r[1] for r in records}}); validation={{e for i,e in enumerate(events) if i%5==0}}\ntrain=[r for r in records if r[1] not in validation]; val=[r for r in records if r[1] in validation]\nif len(train)!=2660 or len(val)!=139: raise RuntimeError(f"Unexpected split cardinalities {{len(train)}}/{{len(val)}}")\nselected=None\nfor record in train:\n    with Image.open(record[2]) as img: width,height=img.size\n    if (width,height)!=(1024,1024): raise RuntimeError("Unexpected image shape")\n    loc,dmg,loc_valid,dmg_valid=_rasterize_xbd_label(record[4],width=width,height=height)\n    top=left=256\n    if dmg_valid[top:top+512,left:left+512].sum()>0:\n        selected=(record,loc,dmg,loc_valid,dmg_valid); break\nif selected is None: raise RuntimeError("No positive labeled center crop found")\nrecord,loc,dmg,loc_valid,dmg_valid=selected\ndef image_tensor(path):\n    with Image.open(path) as im: x=np.asarray(im.convert("RGB"),dtype=np.float32)[256:768,256:768]/255.0\n    x=torch.from_numpy(x.copy()).permute(2,0,1)\n    return ((x-torch.tensor([0.485,0.456,0.406])[:,None,None])/torch.tensor([0.229,0.224,0.225])[:,None,None]).unsqueeze(0).cuda()\nsys.path.insert(0,str(repo[0].parent))\nbackbone=torch.hub.load(str(repo[0].parent),"dinov3_vitl16",source="local",weights=str(weights[0])).eval().cuda()\nfor p in backbone.parameters(): p.requires_grad_(False)\nhead=nn.Sequential(nn.Conv2d(2048,256,1),nn.GroupNorm(32,256),nn.GELU(),nn.Conv2d(256,5,1)).cuda()\noptimizer=torch.optim.AdamW(head.parameters(),lr=3e-4,weight_decay=1e-4)\ndef tokens(x):\n    with torch.no_grad(),torch.autocast(device_type="cuda",dtype=torch.float16): result=backbone.forward_features(x)["x_norm_patchtokens"]\n    if result.shape != (1,1024,1024): raise RuntimeError(f"Unexpected token shape {{tuple(result.shape)}}")\n    return result.float().reshape(1,32,32,1024).permute(0,3,1,2).contiguous()\npre=tokens(image_tensor(record[2])); post=tokens(image_tensor(record[3]))\nlogits=F.interpolate(head(torch.cat([pre,post],dim=1)),size=(512,512),mode="bilinear",align_corners=False)\nloc_crop=loc[256:768,256:768]; dmg_crop=dmg[256:768,256:768]; valid_crop=dmg_valid[256:768,256:768]\nloc_t=torch.from_numpy(loc_crop.copy()).float().unsqueeze(0).unsqueeze(0).cuda(); valid_t=torch.from_numpy(valid_crop.copy()).unsqueeze(0).cuda()\ndmg_t=torch.from_numpy(dmg_crop.copy()).long().unsqueeze(0).cuda().masked_fill(~valid_t,0)\nloc_loss=F.binary_cross_entropy_with_logits(logits[:,:1],loc_t); dmg_loss=F.cross_entropy(logits[:,1:],dmg_t,reduction="none")[valid_t].mean()\nloss=(loc_loss+dmg_loss)*0.5\nif not torch.isfinite(loss): raise RuntimeError("Non-finite supervised loss")\noptimizer.zero_grad();loss.backward()\nif not all(p.grad is not None and torch.isfinite(p.grad).all() for p in head.parameters()): raise RuntimeError("Head gradient missing/non-finite")\noptimizer.step()\nloc_pred=(logits[0,0].detach().sigmoid().cpu().numpy()>=0.5).astype(np.uint8)\ndmg_pred=(logits[0,1:].detach().argmax(dim=0).cpu().numpy()+1).astype(np.uint8)\ndmg_target=np.where(valid_crop,dmg_crop+1,0).astype(np.uint8)\nacc=OfficialAccumulator();acc.update(loc_pred,dmg_pred,loc_crop.astype(np.uint8),dmg_target)\nckpt=Path("/kaggle/working/rv4_corrected_smoke.pt"); torch.save({{"head":head.state_dict(),"optimizer":optimizer.state_dict(),"source_sha256":{digest!r}}},ckpt)\ncopy=nn.Sequential(nn.Conv2d(2048,256,1),nn.GroupNorm(32,256),nn.GELU(),nn.Conv2d(256,5,1)).cuda()\ncopy.load_state_dict(torch.load(ckpt,map_location="cuda",weights_only=False)["head"])\nif not all(torch.equal(a,b) for a,b in zip(head.parameters(),copy.parameters())): raise RuntimeError("Checkpoint reload mismatch")\nreport={{"status":"PASS","purpose":"bounded corrected-label GPU smoke; not benchmark accuracy", "source_sha256":{digest!r},"gpu":torch.cuda.get_device_name(),"sample":record[0],"train_records":len(train),"validation_records":len(val),"building_pixels":int(loc_crop.sum()),"damage_valid_pixels":int(valid_crop.sum()),"localization_loss":float(loc_loss.detach()),"damage_loss":float(dmg_loss.detach()),"optimizer_steps":1,"checkpoint_sha256":hashlib.sha256(ckpt.read_bytes()).hexdigest(),"scorer_smoke":acc.summary()}}\nPath("/kaggle/working/rv4_corrected_smoke.json").write_text(json.dumps(report,indent=2)+"\\n")\nprint(json.dumps(report,indent=2))\n'''
compile(code,'corrected-gpu-smoke','exec')
nb={'cells':[{'cell_type':'code','id':'corrected-smoke','execution_count':None,'metadata':{},'outputs':[],'source':code.splitlines(keepends=True)}],'metadata':{'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'}},'nbformat':4,'nbformat_minor':5}
p=Path(sys.argv[1]);p.mkdir(parents=True,exist_ok=True);(p/'smoke.ipynb').write_text(json.dumps(nb))
meta={'id':'aliomarsaleh/rv4-corrected-supervision-gpu-smoke','title':'RV4 Corrected Supervision GPU Smoke','code_file':'smoke.ipynb','language':'python','kernel_type':'notebook','is_private':True,'enable_gpu':True,'enable_tpu':False,'enable_internet':False,'dataset_sources':['pr4deepr/dinov3-github-repository','tunguz/xview2-challenge-dataset-train-and-test'],'kernel_sources':[],'competition_sources':[],'model_sources':['yadavdamodar/dinov3-vitl16-pretrain-sat493m/PyTorch/default/1'],'machine_shape':'NvidiaTeslaT4'}
(p/'kernel-metadata.json').write_text(json.dumps(meta,indent=2));print('Static JSON and syntax pass; archive SHA-256',digest)
